package cc.ataglace.molebutter.marketplace.internal;

import java.time.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.jupiter.api.*;
import org.springframework.transaction.*;
import org.springframework.transaction.support.*;
import cc.ataglace.molebutter.identity.api.BusinessAccess;
import cc.ataglace.molebutter.common.api.InputValidationFailure;
import cc.ataglace.molebutter.marketplace.api.*;
import cc.ataglace.molebutter.marketplace.api.MarketplaceDrafts.*;
import cc.ataglace.molebutter.marketplace.api.MarketplaceEditing.*;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;

class MarketplaceTargetEditingTest {
    final BusinessAccess access=mock(BusinessAccess.class);
    final MarketplaceDrafts drafts=mock(MarketplaceDrafts.class);
    final DraftStore draftStore=mock(DraftStore.class);
    final SubmissionStore submissions=mock(SubmissionStore.class);
    final EditingStore sessions=mock(EditingStore.class);
    final TargetEditStore pending=mock(TargetEditStore.class);
    final CoupangProductDocuments coupang=mock(CoupangProductDocuments.class);
    final NaverProductDocuments naver=mock(NaverProductDocuments.class);
    final AtomicReference<Document> reference=new AtomicReference<>(),latest=new AtomicReference<>();
    final AtomicReference<EditingStore.Stored> session=new AtomicReference<>();
    final Map<String,MarketplaceWriteGateway.Mapping> mappings=new LinkedHashMap<>();
    final Map<String,TargetEditStore.Saved> pendingValues=new LinkedHashMap<>();
    final PlatformTransactionManager manager=new AbstractPlatformTransactionManager(){
        protected Object doGetTransaction(){return new Object();}protected void doBegin(Object t,TransactionDefinition d){}
        protected void doCommit(DefaultTransactionStatus s){}protected void doRollback(DefaultTransactionStatus s){}
    };
    DefaultMarketplaceEditing service;
    @BeforeEach void setup(){
        when(naver.normalizeChanges(any(),any())).thenAnswer(i->i.getArgument(1));when(coupang.normalizeChanges(any(),any())).thenAnswer(i->i.getArgument(1));
        reference.set(document(0,"공통값","네이버 원래값"));latest.set(document(0,"외부 공통 투영","네이버 원래값"));
        when(coupang.market()).thenReturn("COUPANG");when(coupang.accountKey()).thenReturn("cp-account");when(coupang.supports(any())).thenReturn(true);when(coupang.newDocument(any())).thenAnswer(i->i.getArgument(0));
        when(naver.market()).thenReturn("NAVER");when(naver.accountKey()).thenReturn("nv-account");when(naver.supports(any())).thenReturn(true);when(naver.supportsPendingEdits()).thenReturn(true);when(naver.newDocument(any())).thenAnswer(i->i.getArgument(0));
        when(naver.observeTarget(anyLong(),any(),any())).thenAnswer(i->new MarketplaceProductAdapter.Observation(latest.get(),new NaverEditor.Context(new NaverEditor.Limits(false,false,true,false,""),List.of())));
        when(coupang.observeTarget(anyLong(),any(),any())).thenAnswer(i->new MarketplaceProductAdapter.Observation(latest.get(),null));
        when(naver.apply(any(),any())).thenAnswer(i->{Document d=i.getArgument(0);List<Change> changes=i.getArgument(1);var fields=new LinkedHashMap<>(d.markets().get(Market.NAVER).naver().editorInput().fields());for(var change:changes){if(!"markets.NAVER.naver.editorInput.fields.originProduct.name".equals(change.path()))throw new InputValidationFailure("허용되지 않은 경로");fields.put("originProduct.name",change.value());}return input(d,new NaverEditor.Input(fields,"NONE",List.of(),List.of(),List.of(),""));});
        when(naver.saveTarget(any(),any())).thenAnswer(i->{Document original=i.getArgument(0),desired=i.getArgument(1);return input(original,desired.markets().get(Market.NAVER).naver().editorInput());});
        when(naver.rebase(any(),any(),any())).thenAnswer(i->{Document old=i.getArgument(0),now=i.getArgument(1);List<Change> changes=i.getArgument(2);var remaining=new ArrayList<Change>();var conflicts=new ArrayList<Conflict>();for(var change:changes){Object before=name(old),current=name(now),desired=change.value();if(Objects.equals(current,desired))continue;remaining.add(change);if(!Objects.equals(before,current))conflicts.add(new Conflict(change.path(),change.optionId(),before,current,desired));}return new PendingRebase(remaining,conflicts);});
        when(draftStore.find(eq(10L),anyBoolean())).thenAnswer(i->reference.get());when(drafts.get(1L,"10")).thenAnswer(i->reference.get());when(draftStore.registration(10)).thenReturn(new DraftStore.Registration(1L,null,"COMMON"));
        when(drafts.save(eq(1L),eq("10"),anyLong(),any())).thenAnswer(i->{Document next=i.getArgument(3);var saved=DraftStore.version(next,"10",reference.get().revision()+1);reference.set(saved);return saved;});
        when(submissions.linkedMarkets(10)).thenAnswer(i->new LinkedHashSet<>(mappings.keySet()));when(submissions.mapping(eq(10L),anyString(),anyString(),anyBoolean())).thenAnswer(i->{var mapping=mappings.get(i.getArgument(1));return mapping!=null&&mapping.accountKey().equals(i.getArgument(2))?mapping:null;});
        when(sessions.find(anyLong(),anyBoolean())).thenAnswer(i->session.get());doAnswer(i->{Long actor=i.getArgument(0);Map<String,EditingStore.Binding> bindings=i.getArgument(1);Session next=i.getArgument(2);session.set(new EditingStore.Stored(actor,null,null,next,false,bindings));return null;}).when(sessions).insert(anyLong(),anyMap(),any());
        doAnswer(i->{Session next=i.getArgument(0);session.set(new EditingStore.Stored(1L,null,null,next,false,i.getArgument(1)));return null;}).when(sessions).update(any(),anyMap());
        when(pending.find(eq(10L),anyString(),anyString(),anyBoolean())).thenAnswer(i->pendingValues.get(i.getArgument(1)));
        doAnswer(i->{String market=i.getArgument(3);EditingStore.Binding binding=i.getArgument(4);MarketplaceWriteGateway.EditIntent intent=i.getArgument(5);if(intent.changes().isEmpty())pendingValues.remove(market);else pendingValues.put(market,new TargetEditStore.Saved(i.getArgument(2),1,binding.mapping(),intent));return null;}).when(pending).save(anyLong(),anyLong(),anyLong(),anyString(),any(),any());
        service=new DefaultMarketplaceEditing(access,drafts,draftStore,submissions,sessions,pending,List.of(coupang,naver),manager,mock(cc.ataglace.molebutter.media.api.ImageAssets.class));
    }
    static Document document(long revision,String commonName,String nativeName){
        var input=new NaverEditor.Input(Map.of("originProduct.name",nativeName),"NONE",List.of(),List.of(),List.of(),"");
        var n=new Naver("","SALE","NEW","00","","",List.of(),List.of(),null,false,"ON",input);
        return new Document("10",revision,new Common("SKU",commonName,"製品","共通ブランド","製造","00","材質","型","A/S","TAX","EVERYONE"),List.of(),StockMode.OPTION,"0",List.of(new ServiceOption("00000000-0000-4000-8000-000000000001","서비스",List.of("포장"))),new Media(List.of(),List.of()),null,List.of(Market.COUPANG,Market.NAVER),Map.of(Market.NAVER,new MarketConfig("500001",null,null,n,null),Market.COUPANG,new MarketConfig("123",null,null,null,null)));
    }
    static Document input(Document d,NaverEditor.Input value){var config=d.markets().get(Market.NAVER);var n=config.naver();var nv=new Naver(n.channelId(),n.status(),n.saleType(),n.originCode(),n.deliveryTemplateId(),n.afterServiceTelephone(),n.attributes(),n.notices(),n.channelProductName(),n.naverShoppingRegistration(),n.channelProductDisplayStatusType(),value,n.brandId(),n.editorState());var markets=new EnumMap<Market,MarketConfig>(Market.class);markets.putAll(d.markets());markets.put(Market.NAVER,new MarketConfig(config.categoryCode(),config.overrides(),config.coupang(),nv,config.esm(),config.lotteon()));return new Document(d.id(),d.revision(),d.common(),d.options(),d.stockMode(),d.productQuantity(),d.services(),d.media(),d.delivery(),d.selectedMarkets(),markets);}
    static Object name(Document d){return d.markets().get(Market.NAVER).naver().editorInput().fields().get("originProduct.name");}
    Change change(String value){return new Change("markets.NAVER.naver.editorInput.fields.originProduct.name",null,value);}
    MarketplaceWriteGateway.Mapping mapping(String market){return new MarketplaceWriteGateway.Mapping(market.equals("NAVER")?"nv-account":"cp-account",market.equals("NAVER")?"200":"100",List.of(),market.equals("NAVER")?"300":null);}
    void link(){mappings.put("COUPANG",mapping("COUPANG"));mappings.put("NAVER",mapping("NAVER"));}
    Target naver(Session s){return s.targets().stream().filter(t->t.market().equals("NAVER")).findFirst().orElseThrow();}
    DraftSaveResult save(Session s,String value){return service.saveDraft(1L,s.id(),new DraftSaveRequest(reference.get(),List.of(new TargetChanges("NAVER",List.of(change(value))))));}
    @Test void multiMarketSessionKeepsIndependentAccountsAndMappings(){link();var s=service.start(1L,"10");assertThat(s.targets()).extracting(Target::mode).containsExactly("UPDATE","UPDATE");assertThat(session.get().binding("NAVER").account()).isEqualTo("nv-account");assertThat(session.get().binding("COUPANG").mapping().sellerProductId()).isEqualTo("100");assertThat(reference.get().common().name()).isEqualTo("공통값");}
    @Test void lazyCommonEntryDoesNotReadEitherLinkedProvider(){link();var s=service.startLazy(1L,"10",null);assertThat(s.targets()).extracting(Target::status).containsOnly("UNLOADED");assertThat(s.targets()).extracting(Target::mode).containsOnly("UPDATE");verify(naver,never()).observeTarget(any(),any(),any());verify(coupang,never()).observeTarget(any(),any(),any());}
    @Test void lazyMarketEntryReadsOnlyOriginAndFirstOtherTabLoadsItsPending(){link();pendingValues.put("NAVER",new TargetEditStore.Saved(0,1,mapping("NAVER"),new MarketplaceWriteGateway.EditIntent(latest.get(),List.of(change("보관값")))));var s=service.startLazy(1L,"10","COUPANG");assertThat(naver(s).status()).isEqualTo("UNLOADED");verify(naver,never()).observeTarget(any(),any(),any());var loaded=service.refresh(1L,s.id(),"NAVER");assertThat(naver(loaded).status()).isEqualTo("READY");assertThat(naver(loaded).pendingChanges()).containsExactly(change("보관값"));verify(naver,times(1)).observeTarget(any(),any(),any());verify(coupang,times(1)).observeTarget(any(),any(),any());}
    @Test void savingWithoutVisitingTargetKeepsUpdateModeAndOriginalPending(){link();var remembered=new TargetEditStore.Saved(0,1,mapping("NAVER"),new MarketplaceWriteGateway.EditIntent(latest.get(),List.of(change("보관값"))));pendingValues.put("NAVER",remembered);var s=service.startLazy(1L,"10",null);var saved=service.saveDraft(1L,s.id(),new DraftSaveRequest(reference.get(),List.of()));assertThat(naver(saved.session()).status()).isEqualTo("UNLOADED");assertThat(naver(saved.session()).mode()).isEqualTo("UPDATE");assertThat(pendingValues.get("NAVER")).isSameAs(remembered);verify(naver,never()).newDocument(any());verify(naver,never()).observeTarget(any(),any(),any());}
    @Test void transmissionDeselectionDoesNotDiscardNewProviderInput(){var d=reference.get();reference.set(new Document(d.id(),d.revision(),d.common(),d.options(),d.stockMode(),d.productQuantity(),d.services(),d.media(),d.delivery(),List.of(Market.COUPANG),d.markets()));when(naver.supports(any())).thenAnswer(i->((Document)i.getArgument(0)).selectedMarkets().contains(Market.NAVER));var s=service.startLazy(1L,"10",null);assertThat(naver(s).status()).isEqualTo("READY");var saved=save(s,"미선택 마켓 입력");assertThat(saved.reference().selectedMarkets()).containsExactly(Market.COUPANG);assertThat(name(naver(service.startLazy(1L,"10",null)).document())).isEqualTo("미선택 마켓 입력");}
    @Test void commonImportCanOpenAnotherNewProviderWithoutFirstSavingOrReadingIt(){var d=reference.get();reference.set(new Document(d.id(),d.revision(),d.common(),d.options(),d.stockMode(),d.productQuantity(),d.services(),d.media(),d.delivery(),List.of(Market.COUPANG),Map.of(Market.COUPANG,d.markets().get(Market.COUPANG))));when(naver.supports(any())).thenAnswer(i->((Document)i.getArgument(0)).markets().containsKey(Market.NAVER)&&((Document)i.getArgument(0)).selectedMarkets().contains(Market.NAVER));var s=service.startLazy(1L,"10",null);assertThat(naver(s).mode()).isEqualTo("CREATE");assertThat(naver(s).status()).isEqualTo("READY");assertThat(reference.get().markets()).doesNotContainKey(Market.NAVER);verify(naver,never()).observeTarget(any(),any(),any());assertThat(naver(service.refresh(1L,s.id(),"NAVER")).status()).isEqualTo("READY");}
    @Test void deselectingProviderDoesNotLoseTrustedExistingProductObservation(){link();var d=reference.get();reference.set(new Document(d.id(),d.revision(),d.common(),d.options(),d.stockMode(),d.productQuantity(),d.services(),d.media(),d.delivery(),List.of(Market.COUPANG),d.markets()));when(naver.supports(any())).thenReturn(false);var s=service.start(1L,"10");assertThat(naver(s).mode()).isEqualTo("UPDATE");assertThat(naver(s).status()).isEqualTo("READY");verify(naver).observeTarget(eq(1L),any(),eq(mapping("NAVER")));}
    @Test void anotherMarketMappingChangeDoesNotInvalidateNaverTarget(){link();var s=service.start(1L,"10");mappings.put("COUPANG",new MarketplaceWriteGateway.Mapping("cp-account","999",List.of()));assertThat(service.requireTarget(service.require(1L,s.id(),true),"NAVER",true).mapping().sellerProductId()).isEqualTo("200");assertThatThrownBy(()->service.requireTarget(session.get(),"COUPANG",true)).isInstanceOf(MarketplaceEditingFailure.class);}
    @Test void importedCoupangAccountDoesNotBlockNewNaverTarget(){mappings.put("COUPANG",mapping("COUPANG"));when(submissions.importAccount(10)).thenReturn("cp-account");when(submissions.importMarket(10)).thenReturn("COUPANG");var s=service.start(1L,"10");assertThat(naver(s).mode()).isEqualTo("CREATE");assertThat(session.get().binding("NAVER").mapping()).isNull();}
    @Test void atomicSaveUsesTrustedObservationAndPreservesOtherMarketAndCommon(){link();var s=service.start(1L,"10");var old=reference.get();var result=save(s,"작성값");assertThat(result.reference().revision()).isEqualTo(1);assertThat(result.reference().common()).isEqualTo(old.common());assertThat(result.reference().services()).isEqualTo(old.services());assertThat(result.reference().markets().get(Market.COUPANG)).isEqualTo(old.markets().get(Market.COUPANG));assertThat(name(result.reference())).isEqualTo("작성값");assertThat(pendingValues.get("NAVER").intent().observed()).isEqualTo(latest.get());assertThat(name(naver(result.session()).document())).isEqualTo("네이버 원래값");assertThat(naver(result.session()).pendingChanges()).containsExactly(change("작성값"));verify(naver,never()).observe(anyLong(),any(),any());}
    @Test void nativeInputCannotBypassAllowedChangesThroughReference(){link();var s=service.start(1L,"10");var spoof=input(reference.get(),new NaverEditor.Input(Map.of("originProduct.name","우회값"),"NONE",List.of(),List.of(),List.of(),""));assertThatThrownBy(()->service.saveDraft(1L,s.id(),new DraftSaveRequest(spoof,List.of()))).isInstanceOf(InputValidationFailure.class);verify(drafts,never()).save(any(),any(),any(),any());assertThat(pendingValues).isEmpty();}
    @Test void omittedPendingIsPreservedButExplicitEmptyDiscards(){link();var saved=save(service.start(1L,"10"),"작성값");service.saveReference(1L,saved.session().id(),reference.get());assertThat(pendingValues).containsKey("NAVER");var current=session.get().session();var cleared=service.saveDraft(1L,current.id(),new DraftSaveRequest(reference.get(),List.of(new TargetChanges("NAVER",List.of()))));assertThat(pendingValues).isEmpty();assertThat(naver(cleared.session()).pendingChanges()).isEmpty();}
    @Test void reloadRetainsOriginalBaselineAndReportsExternalConflict(){link();var saved=save(service.start(1L,"10"),"작성값");latest.set(document(saved.reference().revision(),"현재공통","외부값"));var reopened=service.start(1L,"10");assertThat(name(naver(reopened).document())).isEqualTo("외부값");assertThat(naver(reopened).pendingChanges()).containsExactly(change("작성값"));assertThat(naver(reopened).conflicts()).containsExactly(new Conflict(change("").path(),null,"네이버 원래값","외부값","작성값"));assertThat(name(pendingValues.get("NAVER").intent().observed())).isEqualTo("네이버 원래값");}
    @Test void unresolvedConflictCannotBeSilentlyRebasedBySaving(){link();var saved=save(service.start(1L,"10"),"작성값");latest.set(document(saved.reference().revision(),"현재공통","외부값"));var reopened=service.start(1L,"10");assertThatThrownBy(()->save(reopened,"작성값")).isInstanceOf(InputValidationFailure.class);assertThat(name(pendingValues.get("NAVER").intent().observed())).isEqualTo("네이버 원래값");var resolved=service.saveDraft(1L,reopened.id(),new DraftSaveRequest(reference.get(),List.of(new TargetChanges("NAVER",List.of(change("작성값")),List.of(new ConflictKey(change("").path(),null))))));assertThat(naver(resolved.session()).conflicts()).isEmpty();assertThat(name(pendingValues.get("NAVER").intent().observed())).isEqualTo("외부값");}
    @Test void alreadyAppliedDesiredValueIsRetiredBeforeALaterExternalChange(){link();var saved=save(service.start(1L,"10"),"작성값");latest.set(document(saved.reference().revision(),"현재공통","작성값"));var reopened=service.start(1L,"10");assertThat(naver(reopened).pendingChanges()).isEmpty();assertThat(naver(reopened).conflicts()).isEmpty();assertThat(pendingValues).isEmpty();latest.set(document(saved.reference().revision(),"현재공통","나중 외부값"));assertThat(naver(service.start(1L,"10")).pendingChanges()).isEmpty();}
    @Test void activeExecutionDoesNotBlockInternalIntentOrChangeExecutionStatus(){link();var s=service.start(1L,"10");when(submissions.active(10,"nv-account",-1)).thenReturn(true);var saved=save(s,"새작성값");assertThat(saved.reference().revision()).isEqualTo(1);assertThat(pendingValues).containsKey("NAVER");verify(submissions,never()).active(anyLong(),anyString(),anyLong());}
    @Test void missingChangedAccountDoesNotBecomeCreate(){link();when(naver.accountKey()).thenReturn("changed-account");assertThatThrownBy(()->service.start(1L,"10")).isInstanceOf(MarketplaceEditingFailure.class);verify(naver,never()).newDocument(any());}
    @Test void revisionAndActorChecksRunBeforeSavingAnyPending(){link();var s=service.start(1L,"10");assertThatThrownBy(()->service.saveDraft(2L,s.id(),new DraftSaveRequest(reference.get(),List.of()))).isInstanceOf(MarketplaceEditingFailure.class);reference.set(DraftStore.version(reference.get(),"10",1L));assertThatThrownBy(()->save(s,"변경")).isInstanceOf(MarketplaceEditingFailure.class);verify(pending,never()).save(anyLong(),anyLong(),anyLong(),anyString(),any(),any());}
    @Test void mappingComparisonUsesOptionIdsRatherThanListOrder(){var first=new MarketplaceWriteGateway.OptionMapping("a","1",null);var second=new MarketplaceWriteGateway.OptionMapping("b","2",null);assertThat(DefaultMarketplaceEditing.sameMapping(new MarketplaceWriteGateway.Mapping("x","1",List.of(first,second)),new MarketplaceWriteGateway.Mapping("x","1",List.of(second,first)))).isTrue();}
    @Test void storedBindingsRoundTripAndLegacySingleTargetKeepTheirProvider(){var json=new tools.jackson.databind.ObjectMapper();link();service.start(1L,"10");var original=session.get();var restored=json.readValue(json.writeValueAsString(original),EditingStore.Stored.class);assertThat(restored).isEqualTo(original);assertThat(restored.binding("NAVER").account()).isEqualTo("nv-account");var historical=new Session("1","10",0,"2099-01-01T00:00:00Z",List.of(new Target("NAVER","UPDATE","READY",null,null,reference.get())));var old=json.readValue(json.writeValueAsString(new EditingStore.Stored(1L,"nv-account",mapping("NAVER"),historical,false)),EditingStore.Stored.class);assertThat(old.binding("NAVER").mapping()).isEqualTo(mapping("NAVER"));assertThat(old.binding("COUPANG")).isNull();}
    @Test void historicalTargetsGetEmptyPendingAndNoNaverContext(){var json=new tools.jackson.databind.ObjectMapper();var old=json.readValue("{\"market\":\"COUPANG\",\"mode\":\"UPDATE\",\"status\":\"READY\"}",Target.class);assertThat(old.pendingChanges()).isEmpty();assertThat(old.conflicts()).isEmpty();assertThat(old.naverContext()).isNull();}
}
